 const band=(R,n)=>{let d='';for(let i=0;i<n;i++){const a=i/n*Math.PI*2+r()*.04;d+=glyph(50+R*Math.cos(a),50+R*Math.sin(a),2.1,a+Math.PI/2)}return d};
