let tab=LS.get('tab','hero');
const toast=t=>window.toast(t);
function sheet(html,bind){openSheet(html,bind)}
function close(){closeSheet()}

const TABS=[['hero','⚔','Герой'],['bag','⛁','Сумка'],['spells','✧','Чары'],['notes','✎','Записи'],['table','👁','Мастер']];
function nav(){$('#nav').innerHTML=TABS.map(([k,i,l])=>`<button data-tab="${k}" class="${k===tab?'on':''}"><i>${i}</i>${l}</button>`).join('');$$('#nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;LS.set('tab',tab);render();scrollTo(0,0)})}
const can=f=>!window.KP||!KP.linked()||(KP.online()?KP.can(f):f==='notes');
function num(title,cb,ph=''){sheet(`<h3>${esc(title)}</h3><input class="inp" id="nv" type="number" inputmode="numeric" placeholder="${ph}" style="font-size:30px;text-align:center"><div class="row" style="margin-top:10px"><button class="btn red grow" id="nm">− Урон</button><button class="btn ac grow" id="np">＋ Лечение</button></div>`,r=>{setTimeout(()=>$('#nv',r).focus(),50);$('#nm',r).onclick=()=>{cb(-Math.abs(+$('#nv',r).value||0));close()};$('#np',r).onclick=()=>{cb(Math.abs(+$('#nv',r).value||0));close()}})}
function hpChange(v){if(v<0){let d=-v;const a=Math.min(H.thp,d);H.thp-=a;d-=a;H.hp=Math.max(0,H.hp-d);if(H.hp===0&&!H.conds.includes('Без сознания'))H.conds.push('Без сознания')}else{if(H.hp===0){H.ds={s:0,f:0};H.conds=H.conds.filter(c=>c!=='Без сознания')}H.hp=Math.min(H.maxhp,H.hp+v)}save();render()}
function rHero(){const p=pb(H.lvl);
 return `<div class="card"><div class="row"><div class="grow"><div style="font:600 28px/1.1 CG,serif">${esc(H.name)}</div><div class="muted">${esc(H.race)} · ${esc(H.cls)} · ур. ${H.lvl}</div></div><button class="btn sm" id="edit" aria-label="Изменить">✎</button></div><div class="row" style="gap:6px;margin-top:10px"><button class="btn sm grow" id="bNew">🧙 Создать героя</button><button class="btn sm grow" id="bRnd">🎲 Случайный</button><button class="btn sm grow" id="bLvl">⬆ Уровень</button></div></div>
 <div class="card" id="hpc"><div class="hp"><span class="big">${H.hp}</span><small>/ ${H.maxhp}${H.thp?` · +${H.thp} врем.`:''}<br>хиты · нажми, чтобы изменить</small></div><div class="bar"><i style="width:${Math.max(0,H.hp/H.maxhp*100)}%"></i></div>
 ${H.hp===0?`<div class="row" style="margin-top:8px"><span class="muted grow">Спасброски от смерти: ✓${H.ds.s} ✗${H.ds.f}</span><button class="btn sm" data-ds="s">✓</button><button class="btn sm" data-ds="f">✗</button></div>`:''}</div>
 <div class="kv"><div><small>КД</small><b>${H.ac}</b></div><div><small>Иниц.</small><b>${fm(md(H.st[1]))}</b></div><div><small>Скорость</small><b>${H.spd} м</b></div><div><small>Мастерство</small><b>${fm(p)}</b></div></div>
 <h3>Характеристики</h3><div class="stats">${H.st.map((v,i)=>`<div data-ab="${i}"><small>${AB[i]}</small><b>${fm(md(v))}</b><small>${v}${H.svp.includes(i)?' · спас':''}</small></div>`).join('')}</div>
 <h3>Состояния</h3><div>${COND.map(c=>`<button class="chip${H.conds.includes(c)?' on':''}" data-c="${esc(c)}">${c}</button>`).join('')}</div>
 <h3>Навыки</h3><div class="card">${SK.map(([n,a],i)=>{const pr=H.prof.includes(i);return `<div class="it" data-sk="${i}"><span class="grow">${pr?'◆':'◇'} ${n} <span class="muted">${AB[a]}</span></span><b>${fm(md(H.st[a])+(pr?p:0))}</b></div>`}).join('')}</div>
 ${(()=>{const L=window.KP&&KP.linked();const m=L?(KP.mode('rest')):'direct';return m==='off'?`<div class="row"><button class="btn grow" id="sr" aria-disabled="true">🔒 Короткий отдых</button><button class="btn grow" id="lr" aria-disabled="true">🔒 Долгий отдых</button></div><p class="muted" style="font-size:12px;margin:4px 2px 0">Отдых объявляет Мастер — восстановление придёт автоматически.</p>`:`<div class="row"><button class="btn grow" id="sr">☾ Короткий отдых${m==='approve'?' · запрос':''}</button><button class="btn grow" id="lr">☀ Долгий отдых${m==='approve'?' · запрос':''}</button></div>`})()}
 <div class="row" style="margin-top:8px"><button class="btn grow${H.insp?' ac':''}" id="insp">${H.insp?'★ Вдохновение есть':'☆ Вдохновение'}</button></div>`}
function bHero(){$('#edit').onclick=editHero;const bApply=(h,kind)=>{if(window.KP&&KP.linked()){KP.build(h,kind);return}const keep={id:H.id,journal:H.journal,notes:H.notes};Object.assign(H,h,keep);save();render();toast(kind==='lvl'?'⬆ Новый уровень: '+H.lvl:'🧙 Герой «'+H.name+'» готов')};const KB=()=>{if(!window.KMB){toast('Мастер создания загружается…');return false}return true};$('#bNew').onclick=()=>{if(!KB())return;if(H.name&&H.lvl>1&&!confirm('Создать нового героя? Текущий лист будет заменён (дневник и заметки сохранятся).'))return;KMB.open(h=>bApply(h,'new'),{host:'player'})};$('#bRnd').onclick=()=>{if(!KB())return;const h=KMB.random();sheet(`<h3>🎲 ${esc(h.name)}</h3><p class="muted">${esc(h.race)} · ${esc(h.cls)} · ур. ${h.lvl} · КД ${h.ac} · хиты ${h.maxhp}</p><button class="btn red" id="bRok" style="width:100%">Взять этого героя</button>`,r=>{r.querySelector('#bRok').onclick=()=>{close();bApply(h,'new')}})};$('#bLvl').onclick=()=>{if(!KB())return;if(H.lvl>=20)return toast('Уже 20 уровень');KMB.levelUp(H,h=>bApply(h,'lvl'))};$('#hpc').onclick=e=>{if(e.target.closest('[data-ds]'))return;if(!can('hp'))return toast('Хиты меняет Мастер');num('Хиты',hpChange)};
 $$('[data-ds]').forEach(b=>b.onclick=()=>{H.ds[b.dataset.ds]++;if(H.ds.s>=3){H.ds={s:0,f:0};toast('Стабилизирован')}if(H.ds.f>=3)toast('Герой погиб…');save();render()});
 $$('[data-c]').forEach(b=>b.onclick=()=>{if(!can('conds'))return toast('🔒 Состояния назначает Мастер');const c=b.dataset.c;H.conds=H.conds.includes(c)?H.conds.filter(x=>x!==c):[...H.conds,c];save();render()});
 $$('[data-sk]').forEach(b=>b.onclick=()=>roll(SK[+b.dataset.sk][0],md(H.st[SK[+b.dataset.sk][1]])+(H.prof.includes(+b.dataset.sk)?pb(H.lvl):0)));
 $$('[data-ab]').forEach(b=>b.onclick=()=>{const i=+b.dataset.ab;roll('Спасбросок '+AB[i],md(H.st[i])+(H.svp.includes(i)?pb(H.lvl):0))});
 const restGate=k=>{if(!window.KP||!KP.linked())return true;const m=KP.mode('rest');if(m==='off'){toast('🔒 Отдых объявляет только Мастер');return false}if(!KP.online()){toast('Нет связи с Мастером');return false}KP.req('rest',k);toast('Запрос на '+(k==='l'?'долгий':'короткий')+' отдых отправлен Мастеру');return false};
 $('#sr').onclick=()=>{if(!restGate('s'))return;toast('Короткий отдых: потратьте кости хитов');};$('#lr').onclick=()=>{if(!restGate('l'))return;H.hp=H.maxhp;H.thp=0;Object.values(H.slots).forEach(s=>s.used=0);H.conds=H.conds.filter(c=>c!=='Без сознания');save();render();toast('Долгий отдых: всё восстановлено')};
 $('#insp').onclick=()=>{H.insp=!H.insp;save();render()}}
function roll(lbl,mod){const d=1+Math.floor(Math.random()*20);sheet(`<h3>${esc(lbl)}</h3><div style="text-align:center"><div style="font:600 64px CG,serif">${d+mod}</div><div class="muted">к20: ${d} ${fm(mod)}${d===20?' · КРИТ!':d===1?' · провал':''}</div><p class="muted">Бросаете настоящий кубик? Прибавьте ${fm(mod)}.</p></div><button class="btn grow" id="ok" style="width:100%">Готово</button>`,r=>$('#ok',r).onclick=close)}
function editHero(){if(!can('lvl'))return toast('Лист меняет Мастер');if(window.KP&&KP.linked())toast('Изменения уровня и характеристик уйдут Мастеру на одобрение');sheet(`<h3>Герой</h3><input class="inp" id="en" value="${esc(H.name)}" placeholder="Имя"><div class="row" style="margin-top:6px"><input class="inp grow" id="er" value="${esc(H.race)}" placeholder="Народ" style="flex:1"><input class="inp" id="ec" value="${esc(H.cls)}" placeholder="Класс" style="flex:1"></div>
 <div class="row" style="margin-top:6px">${[['el','Уровень',H.lvl],['ea','КД',H.ac],['em','Макс. хиты',H.maxhp],['es','Скорость',H.spd]].map(([i,l,v])=>`<label style="flex:1"><small class="muted">${l}</small><input class="inp" id="${i}" type="number" value="${v}"></label>`).join('')}</div>
 <div class="row" style="margin-top:6px">${H.st.map((v,i)=>`<label style="flex:1;min-width:50px"><small class="muted">${AB[i]}</small><input class="inp" data-st="${i}" type="number" value="${v}"></label>`).join('')}</div>
 <p class="muted">Владение навыками и спасбросками:</p><div>${AB.map((a,i)=>`<button class="chip${H.svp.includes(i)?' on':''}" data-sv="${i}">спас ${a}</button>`).join('')}${SK.map(([n],i)=>`<button class="chip${H.prof.includes(i)?' on':''}" data-pf="${i}">${n}</button>`).join('')}</div>
 <button class="btn red" id="es2" style="width:100%;margin-top:10px">Сохранить</button>`,r=>{const tg=(arr,v)=>arr.includes(v)?arr.filter(x=>x!==v):[...arr,v];
 $$('[data-sv]',r).forEach(b=>b.onclick=()=>{H.svp=tg(H.svp,+b.dataset.sv);b.classList.toggle('on')});$$('[data-pf]',r).forEach(b=>b.onclick=()=>{H.prof=tg(H.prof,+b.dataset.pf);b.classList.toggle('on')});
 $('#es2',r).onclick=()=>{H.name=$('#en',r).value||H.name;H.race=$('#er',r).value;H.cls=$('#ec',r).value;H.lvl=Math.max(1,Math.min(20,+$('#el',r).value||1));H.ac=+$('#ea',r).value||10;H.maxhp=+$('#em',r).value||1;H.hp=Math.min(H.hp,H.maxhp);H.spd=+$('#es',r).value||9;$$('[data-st]',r).forEach(i=>H.st[+i.dataset.st]=+i.value||10);save();close();render()}})}
function bagSorted(){const k=LS.get('bs','');const a=H.inv.slice();if(k==='n')a.sort((x,y)=>x.n.localeCompare(y.n,'ru'));if(k==='w')a.sort((x,y)=>(y.w||0)*(y.q||1)-(x.w||0)*(x.q||1));if(k==='q')a.sort((x,y)=>(y.q||1)-(x.q||1));return a}
function rBag(){const w=H.inv.reduce((s,x)=>s+(x.w||0)*(x.q||1),0);return `<div class="card"><div class="row">${Object.keys(H.coins).map(k=>`<div style="flex:1;text-align:center" data-coin="${k}"><b style="font-size:20px">${H.coins[k]}</b><div class="muted">${k}</div></div>`).join('')}</div></div>
 <div class="row"><input class="inp grow" id="iq" placeholder="${window.KP&&KP.linked()?'Попросить предмет у Мастера…':'Найти предмет и добавить…'}" style="flex:1"></div><div id="ir"></div>
 ${window.KP&&KP.waiting().inv?'<div class="card req">⏳ Изменения сумки ждут одобрения Мастера. Пока Мастер не одобрит — действует его версия.</div>':''}${window.KP&&KP.locked()?'<div class="card req">🔒 Мастер заблокировал лист.</div>':''}<h3>Снаряжение <span class="muted">· ${w.toFixed(1)} кг</span>${H.inv.some(x=>{const i=x.item&&D.items.find(y=>y.id===x.item);return i&&i.att})?` <span class="att-n" title="Настройка: короткий отдых (1 ч) рядом с предметом — и его магия работает на вас. Одновременно можно быть настроенным максимум на 3 предмета." onclick="toast(this.title)">✧ Настроено ${H.inv.filter(x=>x.att).length}/3</span>`:''}</h3><div class="chips">${[['','Как есть'],['n','А–Я'],['w','Тяжёлое'],['q','Больше штук']].map(([k,l])=>`<button class="chip${(LS.get('bs','')===k)?' on':''}" data-bs="${k}">${l}</button>`).join('')}</div><div class="card">${H.inv.length?bagSorted().map(x=>`<div class="it"><div class="grow" data-iv="${x.id}"><div class="t">${esc(x.n)}${x.q>1?' ×'+x.q:''}</div><div class="m">${esc(x.d||'')}</div></div><button class="btn sm" data-iq="${x.id}" data-d="-1">−</button><button class="btn sm" data-iq="${x.id}" data-d="1">＋</button></div>`).join(''):'<div class="pe-empty"><div class="pe-i">🎒</div><b>Сумка пуста</b><small>Найдите предмет поиском выше или добавьте свой. Подключившись к столу, вы получите вещи от Мастера.</small></div>'}</div>
 <button class="btn" id="icust" style="width:100%">＋ Свой предмет</button>`}
function bBag(){$$('[data-bs]').forEach(b=>b.onclick=()=>{LS.set('bs',b.dataset.bs);render()});const inp=$('#iq');inp.oninput=()=>{const q=inp.value.trim().toLowerCase();$('#ir').innerHTML=q.length<2?'':`<div class="card">${D.items.filter(i=>i.n.toLowerCase().includes(q)).slice(0,8).map(i=>`<div class="it" data-add="${i.id}"><div class="grow"><div class="t">${esc(i.n)}</div><div class="m">${esc([i.dmg,i.cost,i.rar].filter(Boolean).join(' · '))}</div></div><b>＋</b></div>`).join('')||'<p class="muted">Ничего</p>'}</div>`;$$('[data-add]').forEach(b=>b.onclick=()=>{if(!can('inv'))return toast('Сумку меняет Мастер');const i=D.items.find(x=>x.id===b.dataset.add);addItem({item:i.id,n:i.n,w:i.w||0,d:[i.dmg,i.prop].filter(Boolean).join(' · ')});inp.value='';render()})};
 $$('[data-iq]').forEach(b=>b.onclick=()=>{if(!can('inv'))return toast('Сумку меняет Мастер');const x=H.inv.find(y=>y.id===b.dataset.iq);x.q=(x.q||1)+(+b.dataset.d);if(x.q<=0){const i=H.inv.indexOf(x);H.inv=H.inv.filter(y=>y!==x);x.q=1;save();render();undoBar('«'+x.n+'» убрано из сумки',()=>{H.inv.splice(Math.min(i,H.inv.length),0,x);save();render()});return}save();render()});
 $$('[data-coin]').forEach(b=>b.onclick=()=>{if(!can('inv'))return toast('Монеты меняет Мастер');const k=b.dataset.coin;sheet(`<h3>${k}</h3><input class="inp" id="cv" type="number" inputmode="numeric" style="font-size:30px;text-align:center" value="${H.coins[k]}"><button class="btn red" id="cok" style="width:100%;margin-top:10px">Сохранить</button>`,r=>{$('#cok',r).onclick=()=>{H.coins[k]=Math.max(0,+$('#cv',r).value||0);save();close();render()}})});
 $$('[data-iv]').forEach(b=>b.onclick=()=>{const x=H.inv.find(y=>y.id===b.dataset.iv);const i=D.items.find(y=>y.id===x.item);sheet(`<h3>${esc(x.n)}</h3>${x.unid?'<p class="muted">Свойства неизвестны — попроси Мастера опознать предмет (заклинание «Опознание» или короткий отдых с предметом).</p>':window.PITEM(i,x)}${i&&i.att&&!x.unid?`<button class="btn${x.att?' ac':''}" id="attb" style="width:100%;margin:6px 0">${x.att?'✧ Настроен — снять настройку':'✧ Настроиться'}</button><p class="muted" style="font-size:12.5px">Настройка: короткий отдых (1 ч) рядом с предметом — и его магия работает на вас. Одновременно можно быть настроенным максимум на 3 предмета.</p>`:''}${window.KP&&KP.linked()&&KP.party().length?`<h3>Передать герою</h3><div>${KP.party().map(p=>`<button class="chip" data-to="${esc(p.id)}">${esc(p.n)}</button>`).join('')}</div><p class="muted">Передача пройдёт после одобрения Мастера.</p>`:''}`,r=>{const ab=$('#attb',r);if(ab)ab.onclick=()=>{if(!can('inv'))return toast('Сумку меняет Мастер');const y=H.inv.find(z=>z.id===x.id);if(!y)return close();if(!y.att&&H.inv.filter(y=>y.att).length>=3)return toast('Уже настроено 3 предмета — сначала снимите настройку с другого');y.att=y.att?0:1;save();close();render();toast(y.att?'✧ Настроен: '+y.n:'Настройка снята')};$$('[data-to]',r).forEach(t=>t.onclick=()=>{if(!can('trade'))return toast('Обмен отключён Мастером');KP.trade(x.id,t.dataset.to);close()})})});
 $('#icust').onclick=()=>{if(!can('inv'))return toast('Сумку меняет Мастер');sheet(`<h3>Свой предмет</h3><input class="inp" id="cn" placeholder="Название"><input class="inp" id="cd" placeholder="Описание" style="margin-top:6px"><button class="btn red" id="cok" style="width:100%;margin-top:10px">Добавить</button>`,r=>{$('#cok',r).onclick=()=>{addItem({n:$('#cn',r).value||'Предмет',d:$('#cd',r).value,w:0});close();render()}})}}
function addItem(o){const ex=o.item&&H.inv.find(x=>x.item===o.item);if(ex)ex.q=(ex.q||1)+1;else H.inv.push({id:uid(),q:1,...o});save();toast('Добавлено: '+o.n)}
const SLOTS=[[],[2],[3],[4,2],[4,3],[4,3,2],[4,3,3],[4,3,3,1],[4,3,3,2],[4,3,3,3,1],[4,3,3,3,2],[4,3,3,3,2,1],[4,3,3,3,2,1],[4,3,3,3,2,1,1],[4,3,3,3,2,1,1],[4,3,3,3,2,1,1,1],[4,3,3,3,2,1,1,1],[4,3,3,3,2,1,1,1,1],[4,3,3,3,3,1,1,1,1],[4,3,3,3,3,2,1,1,1],[4,3,3,3,3,2,2,1,1]];
function rSpells(){const ks=Object.keys(H.slots).sort();return `<div class="card"><div class="row"><b class="grow">Ячейки заклинаний</b><button class="btn sm" id="sfill">По уровню</button></div>${ks.length?ks.map(l=>`<div class="row" style="margin-top:8px"><span style="width:56px" class="muted">${l} ур.</span><div class="slots">${Array.from({length:H.slots[l].max},(_,i)=>`<button class="pip${i<H.slots[l].used?' used':''}" data-sl="${l}" data-i="${i}" aria-label="Ячейка"></button>`).join('')}</div></div>`).join(''):'<p class="muted">Нет ячеек. Нажми «По уровню» для заклинателя.</p>'}</div>
 <input class="inp" id="sq" placeholder="Найти заклинание и выучить…"><div id="sr2"></div>
 <h3>Мои заклинания</h3><div style="display:flex;flex-wrap:wrap;gap:6px;margin:6px 0">${[['l','По уровню'],['n','А–Я'],['c','Концентрация'],['z','Заговоры'],['r','Ритуалы']].map(([k,t])=>`<button class="btn sm ${(localStorage.kp_ss||'l')===k?'ac':''}" data-ss="${k}" style="margin:0">${t}</button>`).join(' ')}</div><div class="card">${H.spells.length?H.spells.map(id=>D.spells.find(s=>s.id===id)).filter(Boolean).filter(s=>{const m=localStorage.kp_ss||'l';return m==='c'?s.conc:m==='r'?s.rit:m==='z'?!s.l:1}).sort((a,b)=>(localStorage.kp_ss==='n')?a.n.localeCompare(b.n,'ru'):a.l-b.l||a.n.localeCompare(b.n,'ru')).map(s=>`<div class="it" data-sp="${s.id}"><div class="grow"><div class="t">${esc(s.n)}</div><div class="m">${s.l?s.l+' ур.':'заговор'} · ${esc(s.t)} · ${esc(s.r)}${s.conc?' · концентрация':''}${s.rit?' · ритуал':''}</div></div>${s.l?`<button class="btn sm ac" data-cast="${s.id}">Применить (ячейка)</button>`:''}</div>`).join(''):'<div class="pe-empty"><div class="pe-i">✨</div><b>Заклинаний пока нет</b><small>Найдите заклинание поиском выше и нажмите «Выучить».</small></div>'}</div>`}
function bSpells(){$('#sfill').onclick=()=>{const a=SLOTS[H.lvl]||[];H.slots={};a.forEach((m,i)=>H.slots[i+1]={max:m,used:0});save();render()};
 $$('[data-sl]').forEach(b=>b.onclick=()=>{if(!can('slots'))return toast('Ячейки меняет Мастер');const s=H.slots[b.dataset.sl];const i=+b.dataset.i;s.used=i<s.used?i:i+1;save();render()});
 const q=$('#sq');q.oninput=()=>{const v=q.value.trim().toLowerCase();$('#sr2').innerHTML=v.length<2?'':`<div class="card">${D.spells.filter(s=>s.n.toLowerCase().includes(v)).slice(0,8).map(s=>`<div class="it" data-learn="${s.id}"><div class="grow"><div class="t">${esc(s.n)}</div><div class="m">${s.l?s.l+' ур.':'заговор'} · ${esc(s.sc)}</div></div><b>${H.spells.includes(s.id)?'✓':'＋'}</b></div>`).join('')}</div>`;$$('[data-learn]').forEach(b=>b.onclick=()=>{const id=b.dataset.learn;if(!H.spells.includes(id))H.spells.push(id);save();q.value='';render();toast('Записано в гримуар')})};
 $$('[data-ss]').forEach(b=>b.onclick=()=>{localStorage.kp_ss=b.dataset.ss;render()});$$('[data-sp]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-cast]'))return;const s=D.spells.find(x=>x.id===b.dataset.sp);sheet(`<h3>${esc(s.n)}</h3>${PSPELL(s)}<button class="btn dark" id="forget" style="width:100%">Забыть</button>`,r=>$('#forget',r).onclick=()=>{const o=H.spells.slice();H.spells=H.spells.filter(x=>x!==s.id);save();close();render();undoBar('Заклинание забыто',()=>{H.spells=o;save();render()})})});
 $$('[data-cast]').forEach(b=>b.onclick=()=>{if(!can('slots'))return toast('Ячейки меняет Мастер');const s=D.spells.find(x=>x.id===b.dataset.cast);const lv=Object.keys(H.slots).filter(l=>+l>=s.l&&H.slots[l].used<H.slots[l].max);if(!lv.length)return toast('Нет свободных ячеек');sheet(`<h3>${esc(s.n)}</h3><p class="muted">Какой ячейкой?</p><div>${lv.map(l=>`<button class="btn ac" data-use="${l}" style="margin:4px">${l} ур.</button>`).join('')}</div>`,r=>$$('[data-use]',r).forEach(x=>x.onclick=()=>{H.slots[x.dataset.use].used++;if(s.conc&&!H.conds.includes('Концентрация'))H.conds.push('Концентрация');save();close();render();toast(s.n+' — сотворено')}))})}
function roBan(){return window.KP&&KP.linked()&&!KP.online()?`<div class="card" style="border-color:#a66;font-size:13.5px">🔒 Нет связи с Мастером — лист только для чтения. Записи можно вести; при подключении Мастер пришлёт актуальный лист.</div>`:''}
function usesCard(){const U=H.uses||{},A=H.usesA||{};const ks=Object.keys(U);if(!ks.length)return '';return `<h3>Ресурсы и заряды</h3><div class="card">${ks.map(k=>{const u=U[k];return `<div class="it"><div class="grow"><div class="t">${esc(u.n)}</div><div class="m">${u.used&&A[k]?'↻ снова '+esc(A[k]):'готово'}</div></div><b style="color:${u.used>=u.max?'#a66':'#e8c77a'}">${u.max-u.used}/${u.max}</b></div>`}).join('')}<p class="muted" style="font-size:12px;margin:6px 0 0">Тратит и восстанавливает Мастер — по игровому времени и отдыху.</p></div>`}
function rNotes(){const ho=LS.get('handouts',[]);return `${ho.length?`<h3>От Мастера</h3>${ho.map((h,i)=>window.KMH?KMH.card(h,`data-ho="${i}"`).replace('hx-card',(LS.get('hoNew',[]).includes(i)?'hx-card hx-new':'hx-card')):`<div class="card req"><b>${esc(h.n)}</b><div style="white-space:pre-wrap">${esc(h.t||'')}</div></div>`).join('')}<p class="muted" style="font-size:12px;margin:2px 0 8px">Нажмите на записку — откроется во весь экран.</p>`:''}
 <h3>Мои записи</h3><div class="row" style="justify-content:flex-end;margin:-4px 0 4px"><button class="btn sm" id="ntc">Очистить</button></div><textarea class="inp" id="nt" placeholder="Имена, долги, подозрения…">${esc(H.notes)}</textarea>
 <h3>Дневник</h3><div class="row"><input class="inp grow" id="jq" placeholder="Что случилось сегодня?" style="flex:1"><button class="btn" id="ja">＋</button></div><div class="card">${H.journal.map((j,i)=>`<div class="it jr" data-ji="${i}"><span class="muted">${esc(j.d)}</span><span class="grow" style="white-space:pre-wrap">${esc(j.t)}</span><button class="btn sm" data-je="${i}" aria-label="Изменить">✎</button><button class="btn sm" data-jd="${i}" aria-label="Удалить">✕</button></div>`).join('')||'<div class="pe-empty"><div class="pe-i">🪶</div><b>Дневник пуст</b><small>Запишите, что случилось сегодня, — долги, имена, подсказки. Удерживайте запись, чтобы изменить.</small></div>'}</div>`}
function bNotes(){$('#ntc').onclick=()=>{if(!H.notes||!confirm('Очистить «Мои записи»?'))return;const o=H.notes;H.notes='';save();render();undoBar('Записи очищены',()=>{H.notes=o;save();render()})};$('#nt').oninput=e=>{H.notes=e.target.value;clearTimeout(bNotes.t);bNotes.t=setTimeout(save,500)};$('#ja').onclick=()=>{const t=$('#jq').value.trim();if(!t)return;H.journal.unshift({d:new Date().toLocaleDateString('ru-RU'),t});save();render()};
 const del=i=>{const j=H.journal[i];if(!j||!confirm('Удалить запись «'+j.t.slice(0,40)+'»?'))return;H.journal.splice(i,1);save();render();undoBar('Запись удалена',()=>{H.journal.splice(Math.min(i,H.journal.length),0,j);save();render()})};
 const edit=i=>{const j=H.journal[i];if(!j)return;sheet(`<h3>Изменить запись</h3><textarea class="inp" id="jet" style="min-height:120px">${esc(j.t)}</textarea><div class="row" style="margin-top:8px"><button class="btn ac grow" id="jes">Сохранить</button><button class="btn" id="jed">Удалить</button></div>`,r=>{$('#jes',r).onclick=()=>{const t=$('#jet',r).value.trim();if(!t)return toast('Пустая запись');j.t=t;save();close();render();toast('Сохранено')};$('#jed',r).onclick=()=>{close();del(i)}})};
 $$('[data-jd]').forEach(b=>b.onclick=e=>{e.stopPropagation();del(+b.dataset.jd)});$$('[data-je]').forEach(b=>b.onclick=e=>{e.stopPropagation();edit(+b.dataset.je)});
 $$('[data-ji]').forEach(r=>{let t,x0;r.addEventListener('touchstart',e=>{x0=e.touches[0].clientX;t=setTimeout(()=>edit(+r.dataset.ji),550)},{passive:true});r.addEventListener('touchmove',e=>{clearTimeout(t);if(x0-e.touches[0].clientX>70){x0=1e9;del(+r.dataset.ji)}},{passive:true});r.addEventListener('touchend',()=>clearTimeout(t))})}
function undoBar(msg,fn){document.querySelector('.undob')?.remove();const d=document.createElement('div');d.className='undob';d.innerHTML=`<span>${esc(msg)}</span><button class="btn sm ac">Вернуть</button>`;document.body.appendChild(d);d.querySelector('button').onclick=()=>{fn();d.remove()};setTimeout(()=>d.remove(),6000)}
function rTable(){return window.KP&&KP.render?KP.render():`<div class="card"><h3>Связь со столом Мастера</h3><p class="soon">Живая связь — скоро.</p><p class="muted">Пока можно передать героя Мастеру кодом.</p><button class="btn" id="exp" style="width:100%">Скопировать код героя</button><textarea class="inp" id="imp" placeholder="Вставьте код героя от Мастера" style="margin-top:8px;min-height:80px"></textarea><button class="btn ac" id="impb" style="width:100%;margin-top:6px">Загрузить героя</button></div>`}
function bTable(){if(window.KP&&KP.bind)return KP.bind();$('#exp').onclick=()=>{const c='KP1:'+btoa(unescape(encodeURIComponent(JSON.stringify(H))));navigator.clipboard?.writeText(c).then(()=>toast('Код скопирован'),()=>{$('#imp').value=c;toast('Код в поле ниже')})};$('#impb').onclick=()=>{try{const v=$('#imp').value.trim().replace(/^KP1:/,'');const h=JSON.parse(decodeURIComponent(escape(atob(v))));H=Object.assign(fresh(),h);save();toast('Герой загружен');render()}catch(e){toast('Неверный код')}}}
const RN={hero:[()=>roBan()+rHero()+usesCard(),bHero],bag0:0,bag:[()=>roBan()+rBag(),bBag],spells:[rSpells,bSpells],notes:[rNotes,bNotes],table:[rTable,bTable]};
const HD={hero:['Герой',()=>H.name+' · '+H.cls+' '+H.lvl+' ур.','pent'],bag:['Сумка',()=>'снаряжение и монеты','star'],spells:['Чары',()=>'ячейки и заклинания','eye'],notes:['Записи',()=>'дневник и послания Мастера','tri'],table:['Мастер',()=>'всё, что показывает Мастер','pent']};
window.PRN=function(i){tab=TABS[i][0];LS.set('tab',tab);const h=HD[tab];page.oninput=null;page.innerHTML=header(h[0],h[1](),h[2],i)+'<div class="pbk">'+RN[tab][0]()+'</div>';RN[tab][1]()};
function render(){const y=page.scrollTop,h0=page.scrollHeight;PRN(S.sec);if(page.scrollHeight<h0){const sp=document.createElement('div');sp.className='rnd-sp';sp.style.height=(h0-page.scrollHeight)+'px';page.appendChild(sp)}page.scrollTop=y;const fix=()=>{if(Math.abs(page.scrollTop-y)>2)page.scrollTop=y};requestAnimationFrame(fix);clearTimeout(render.t);render.t=setTimeout(()=>{page.querySelectorAll('.rnd-sp').forEach(x=>x.remove());fix();requestAnimationFrame(fix)},450)}
